CREATE TABLE lesson_participants(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,lesson_id TEXT NOT NULL,student_id TEXT NOT NULL,attendance TEXT NOT NULL DEFAULT 'planned',deducted REAL NOT NULL DEFAULT 0,package_id TEXT,makeup_for TEXT,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,lesson_id) REFERENCES lessons(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,package_id) REFERENCES packages(tenant_id,id));
